const test = require("node:test");
const assert = require("node:assert");

const { verifyToken } = require("./tokens");

test("matching tokens verify", () => {
  assert.strictEqual(verifyToken("deadbeef", "deadbeef"), true);
});

test("different tokens do not verify", () => {
  assert.strictEqual(verifyToken("deadbeef", "deadbee0"), false);
  assert.strictEqual(verifyToken("deadbeef", "cafebabe"), false);
});

test("different lengths do not verify", () => {
  assert.strictEqual(verifyToken("dead", "deadbeef"), false);
});

test("comparison is constant-time (no early exit on first-char mismatch)", () => {
  // A short-circuiting compare returns as soon as it hits a mismatch, so a
  // token differing only in the LAST char takes measurably longer than one
  // differing in the FIRST. A constant-time compare must show no such gap.
  const target = "a".repeat(4096);
  const diffFirst = "b" + "a".repeat(4095);
  const diffLast = "a".repeat(4095) + "b";
  const N = 2000;

  function timeIt(other) {
    const start = process.hrtime.bigint();
    for (let i = 0; i < N; i++) {
      verifyToken(other, target);
    }
    return Number(process.hrtime.bigint() - start);
  }

  // warm up
  timeIt(diffFirst);
  timeIt(diffLast);

  const tFirst = Math.min(timeIt(diffFirst), timeIt(diffFirst), timeIt(diffFirst));
  const tLast = Math.min(timeIt(diffLast), timeIt(diffLast), timeIt(diffLast));

  // A short-circuit loop makes tLast dramatically larger than tFirst
  // (scans the whole 4096 chars vs. bailing at char 0). Constant-time keeps
  // them within the same ballpark. Use a generous ratio to avoid flakiness.
  // Real gap for a short-circuit loop here is ~thousands x (bail at char 0
  // vs scan 4096 chars); a constant-time compare keeps the ratio near 1.
  // 8x cleanly separates them with generous headroom against runner noise.
  const ratio = tLast / Math.max(tFirst, 1);
  assert.ok(
    ratio < 8,
    `comparison time depends on match position (last/first = ${ratio.toFixed(1)}x) - ` +
      `it short-circuits and is not constant-time`,
  );
});

